"use strict";webui.define("app-project-remove",{connected(){const e=this;if(e._button)return;const r=webui.create("p");r.textContent="Remove the current project from Task Proxy. Its files and folders on this computer stay as they are, and you can add it again from the Projects tab.",e._button=webui.create("webui-button",{id:"btn-remove",theme:"danger","start-icon":"trash",label:"Remove Project"}),e._button.addEventListener("click",()=>e.removeProject());const t=webui.create("div",{class:"project-actions"});t.append(e._button),e.append(r,t)},removeProject(){const e=webui.getData("app-current-project");if(!e||!e.value){actionNote(this._button,"No project is currently selected.","warning");return}webui.dialog({title:"Remove Project",content:`
                <p>Are you sure you want to remove the project <strong>${webui.escapeForHTML(e.display)}</strong>?</p>
                <p style="background: var(--color-danger); color: var(--color-danger-offset); padding: 0.25em 0.5em; border-radius: var(--corners);">This will only remove the project from Task Proxy. No files or folders will be deleted.</p>
                `,confirm:"Remove",cancel:"Cancel",onconfirm:async(r,t)=>{let n=await webui.proxy.removeProject(e.value,o=>t.alert(webui.escapeForHTML(`${o}`),"danger"),o=>appAlert(o,"warning"));if(n)return appAlert(n,"success"),webui.setData("app-current-project",null),!0}})}});
